from typing import List
from math import gcd


class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        mod = 10**9 + 7
        m = max(nums)
        g = [[gcd(a, b) for b in range(m + 1)] for a in range(m + 1)]
        dp = {(0, 0): 1}
        for v in nums:
            row = g[v]
            nxt = dict(dp)
            for (a, b), cnt in dp.items():
                key = (row[a], b)
                nxt[key] = (nxt.get(key, 0) + cnt) % mod
                key = (a, row[b])
                nxt[key] = (nxt.get(key, 0) + cnt) % mod
            dp = nxt
        total = 0
        for (a, b), cnt in dp.items():
            if a == b and a > 0:
                total += cnt
        return total % mod

